def verifier_format(donnees: dict) -> None:
    """Toute différence de format entre le banc et la lecture arrête avec un message (jamais une trace) : lignes, ordre
    des répétitions, champs et sous-champs lus, types (n7), et absences de groupes réductibles conformes à la règle de
    réduction (première absence à une borne de la règle, groupes absents ensemble, jamais de réapparition : C1, n6)."""
    if not isinstance(donnees, dict) or set(donnees) != set(B.NOMS):
        raise GardeArret("format : lignes absentes ou en trop : lecture refusée")
    for l, recs in donnees.items():
        if not isinstance(recs, list) or not recs:
            raise GardeArret(f"format : ligne {l} sans répétition : lecture refusée")
        sorte = "V" if l in V else ("Q9" if l in ("Q9a", "Q9b") else None)
        bornes = BORNES_REDUCTION.get(sorte, {})
        if l in B.LIGNES_H:
            exiges = dict(CHAMPS_H, **({} if l == "H7" else CHAMPS_H_JUGE))
            exiges["temoin_lambda"] = ("promue", "max")
            possibles = {}
        else:
            exiges = dict(CHAMPS_SANS_MEMOIRE)
            possibles = dict(CHAMPS_TOUJOURS_SANS_MEMOIRE)
            if l in FATALES_HOLM or l in FATALES_HORS_HOLM:
                possibles["J9-D"] = ("promue", "quantite_fatale")
            for cle in list(possibles):
                if cle not in bornes:
                    exiges[cle] = possibles.pop(cle)
        absents_depuis = {}
        for k, r in enumerate(recs):
            if not isinstance(r, dict) or "r" not in r or r["r"] != k:
                _arret(l, k, "enregistrement illisible, sans « r » ou hors d'ordre")
            for cle, sous in exiges.items():
                if cle not in r:
                    _arret(l, k, f"champ « {cle} » absent")
                for s in (sous or ()):
                    if s not in r[cle]:
                        _arret(l, k, f"champ « {cle}.{s} » absent")
                if sous is None:
                    if not isinstance(r[cle], list) or not all(isinstance(x, (int, float)) and not isinstance(x, bool) for x in r[cle]):
                        _arret(l, k, f"« {cle} » n'est pas une liste de nombres")
                else:
                    _types(l, k, cle, r[cle])
            for cle, sous in possibles.items():
                if cle in r:
                    if cle in absents_depuis:
                        raise GardeArret(f"format : ligne {l} : « {cle} » réapparaît après une réduction : lecture refusée")
                    for s in sous:
                        if s not in r[cle]:
                            _arret(l, k, f"champ « {cle}.{s} » absent")
                    _types(l, k, cle, r[cle])
                else:
                    absents_depuis.setdefault(cle, k)
            if "strate_sans_log" in r:
                for b, d in r["strate_sans_log"].items():
                    _types(l, k, f"strate_sans_log.{b}", d)
                    if "promue" not in d:
                        _arret(l, k, f"« strate_sans_log.{b}.promue » absent")
        for cle, k in absents_depuis.items():
            if k not in bornes.get(cle, ()):
                raise GardeArret(f"format : ligne {l} : « {cle} » absent dès la répétition {k}, hors des bornes de la règle "
                                 f"de réduction {bornes.get(cle, ())} : lecture refusée")
        for nom, membres in GROUPES_REDUCTIBLES.items():
            debuts = {absents_depuis.get(c) for c in membres if c in possibles}
            if len(debuts) > 1:
                raise GardeArret(f"format : ligne {l} : groupe « {nom} » retiré en partie seulement : lecture refusée")
        # C1 : une ligne V porte toujours le jumeau et La-P à sa première répétition (la règle en garde au moins 250 et 500)
